fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();
    
    // Iterate through all parent nodes
    for i in 0..n / 2 {
        let left_child = 2 * i + 1;
        let right_child = 2 * i + 2;
        
        // Check left child
        if left_child < n && a[i] > a[left_child] {
            return false;
        }
        
        // Check right child
        if right_child < n && a[i] > a[right_child] {
            return false;
        }
    }
    
    true
}